import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import bcBoundary from './bc-boundary.json';
import {hospitals,resources,distance} from './seed.js';
import {hospitalById,recipientIds,isIncoming,isRelevant} from './request-utils.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
const deskRole=params.get('role')==='hospital'?'hospital':'ems';
const modes={active:'Active requests',incoming:'Incoming requests',nearby:'BC hospital map',completed:'Completed requests'};
let view=params.get('view')||(location.pathname==='/network.html'?'nearby':'active');if(!modes[view])view='active';
let current=hospitals.some(h=>h.id===params.get('hospital'))?params.get('hospital'):'cedar';
let ready=[],requests=[],states={},selected=params.get('selected'),resource='All resources',availability='All availability',radius=Number.isInteger(Number(params.get('radius')))&&Number(params.get('radius'))>=1&&Number(params.get('radius'))<=2000?Number(params.get('radius')):100,search='';
let map,markers=L.layerGroup(),radiusLayer,tiles,boundaryLayer,tilesFailed=false;
const name=id=>hospitalById(id)?.name||'Unknown sample hospital';
const updated=h=>h.updatedAt?new Date(h.updatedAt).toLocaleString():'Initial sample status';
const route=(mode,id=current)=>`${mode==='nearby'?'/network.html':'/requests.html'}?hospital=${id}&role=${deskRole}&view=${mode}`;
const tag=(text,kind='')=>`<span class="tag ${kind}">${esc(text)}</span>`;
async function read(path){const r=await fetch(path);if(!r.ok)throw new Error('Could not load saved network information. Try Refresh.');return r.json();}
function layout(){
 $('#overview').innerHTML=`<main class="overview-wrap"><header class="overview-head"><a href="/?role=${deskRole}&hospital=${current}" data-testid="back-dashboard">← Back to dashboard</a><strong class="brand-title">Hospital Connect</strong>${tag('SHARED DEMO')}</header><div class="banner map-data-banner" id="map-data-notice" data-testid="map-data-notice">Real BC geography. <strong>Fictional hospital locations, resources and manually entered availability.</strong> This app does not show verified capacity, road travel times or send ambulance dispatches.</div><nav class="overview-nav" aria-label="Network views">${Object.entries(modes).filter(([key])=>deskRole==='hospital'||key!=='incoming').map(([key,label])=>`<a href="${route(key)}" ${key===view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="heading overview-title"><div><div class="eyebrow">YOUR HOSPITAL NETWORK</div><h1>${modes[view]}</h1><p>${view==='nearby'?'Explore the map, compare availability and select a hospital to inspect its details.':'See who sent each request, its recipients, responses and accepted destination.'}</p></div><button class="secondary" id="refresh-overview" data-testid="refresh-overview">Refresh</button></div><div id="overview-error" role="alert"></div><section class="panel"><div class="overview-toolbar"><label class="field origin-field"><span>${deskRole==='ems'?'EMS dispatch base':'Hospital desk'}</span><select id="overview-hospital" data-testid="overview-hospital">${hospitals.map(h=>`<option value="${h.id}" ${h.id===current?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label>${view==='nearby'?`<label class="field"><span>Resource</span><select id="map-resource" data-testid="map-resource"><option>All resources</option>${resources.map(r=>`<option>${r}</option>`).join('')}</select></label><label class="field"><span>Availability</span><select id="map-availability" data-testid="map-availability">${['All availability','Open','Limited','Closed'].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field"><span>Radius (km)</span><input id="map-radius" data-testid="map-radius" type="number" min="1" max="2000" step="1" value="${radius}" required><small id="radius-error" role="alert"></small></label>`:'<label class="field" style="grid-column:span 2"><span>Find a request or hospital</span><input type="search" id="ledger-search" data-testid="ledger-search" placeholder="Request, resource, sender or destination"></label>'}</div></section>${view==='nearby'?`<div class="map-layout"><section class="panel"><div class="map-actions"><button class="secondary" id="fit-nearby" data-testid="fit-nearby">Fit nearby hospitals</button><button class="secondary" id="fit-bc" data-testid="fit-bc">Show all BC</button></div><div id="bc-map" class="map-surface" data-testid="bc-map" role="region" aria-label="Interactive British Columbia hospital map"></div><div class="map-legend"><span><i class="legend-dot origin"></i>${deskRole==='ems'?'EMS base':'Your hospital'}</span><span><i class="legend-dot"></i>Open</span><span><i class="legend-dot limited"></i>Limited</span><span><i class="legend-dot closed"></i>Closed</span></div><label class="map-layer-switch"><input id="street-tiles" type="checkbox" ${params.get('tiles')!=='off'?'checked':''}>Show OpenStreetMap street tiles</label><p class="source-note" id="map-geography-status" data-testid="map-geography-status">British Columbia · Local BC outline available.</p><p class="source-note">Boundary: Statistics Canada via <a href="https://www.geoboundaries.org/" target="_blank" rel="noreferrer">geoBoundaries</a>, simplified for display. <a href="/map-attribution.txt">Map data and library credits</a>. Circle distance is straight-line, not a road route.</p><h2>Nearby matches <span id="map-count" class="map-count"></span></h2><div id="map-results" class="map-results" data-testid="map-results"></div></section><aside id="hospital-map-detail" class="panel map-selected" data-testid="hospital-map-detail"><h2>Select a hospital</h2><p class="muted">Click a marker or choose a hospital from the nearby list.</p></aside></div>`:'<section class="panel" style="margin-top:20px"><div class="ledger-summary"><p id="ledger-count" class="muted"></p><small>In-app request routing only. No external notification delivery is claimed.</small></div><div class="table-wrap"><table class="ledger-table"><thead><tr><th>Request</th><th>Sent by / location</th><th>Recipients</th><th>Hospital acceptance</th><th>Accepted destination</th><th>Action</th></tr></thead><tbody id="ledger-body" data-testid="ledger-body"></tbody></table></div><div id="ledger-empty"></div></section>'}</main>`;
 $('#overview-hospital').onchange=e=>location.assign(route(view,e.target.value));
 $('#refresh-overview').onclick=refresh;
 if(view==='nearby')initMap();else{$('#ledger-search').value=search;$('#ledger-search').oninput=e=>{search=e.target.value;renderLedger();};renderLedger();}
}
function filtered(){const origin=hospitalById(current);return ready.filter(h=>h.id!==current&&distance(origin,h)<=radius&&(resource==='All resources'||h.resources.includes(resource))&&(availability==='All availability'||h.state===availability)).sort((a,b)=>distance(origin,a)-distance(origin,b));}
function initMap(){
 map=L.map('bc-map',{scrollWheelZoom:false,minZoom:4,maxZoom:15}).setView([49.3,-123],9);
 boundaryLayer=L.geoJSON(bcBoundary,{style:{color:'#71978b',weight:1,fillColor:'#eaf1e3',fillOpacity:.5},interactive:false}).addTo(map);
 for(const [label,lat,lng] of [['Vancouver',49.28,-123.12],['Victoria',48.43,-123.37],['Kelowna',49.89,-119.50],['Kamloops',50.67,-120.33],['Prince George',53.92,-122.75],['Terrace',54.52,-128.60]])L.circleMarker([lat,lng],{radius:2,color:'#62758a',interactive:false}).bindTooltip(label,{permanent:true,direction:'right',className:'place-label'}).addTo(map);
 markers.addTo(map);updateMap();fitNearby();
 updateGeographyStatus();
 if($('#street-tiles').checked){const startTiles=()=>setTimeout(()=>{if($('#street-tiles')?.checked&&!tiles)enableTiles();},100);if(document.readyState==='complete')startTiles();else window.addEventListener('load',startTiles,{once:true});}
 $('#street-tiles').onchange=e=>{if(e.target.checked)enableTiles();else{if(tiles)map.removeLayer(tiles);tiles=undefined;tilesFailed=false;updateGeographyStatus();}};
 $('#fit-bc').onclick=()=>{map.fitBounds(boundaryLayer.getBounds(),{padding:[15,15]});updateGeographyStatus();};
 $('#fit-nearby').onclick=fitNearby;
 $('#map-resource').value=resource;$('#map-availability').value=availability;
 $('#map-resource').onchange=e=>{resource=e.target.value;updateMap();};
 $('#map-availability').onchange=e=>{availability=e.target.value;updateMap();};
 $('#map-radius').oninput=e=>{const value=Number(e.target.value);if(Number.isInteger(value)&&value>=1&&value<=2000){$('#radius-error').textContent='';radius=value;updateMap();}else{$('#radius-error').textContent=`Enter a whole number from 1 to 2000. The map still uses ${radius} km.`;}};
}
function enableTiles(){
 if(tiles)return;
 tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>',maxZoom:15,referrerPolicy:'strict-origin-when-cross-origin'}).addTo(map);
 tiles.on('tileerror',()=>{tilesFailed=true;updateGeographyStatus();});tiles.on('load',updateGeographyStatus);updateGeographyStatus();
}
function updateGeographyStatus(){$('#map-geography-status').textContent=`British Columbia · Local BC outline ${!tiles?'mode. Street tiles are off.':tilesFailed?'remains available; street tiles could not fully load. Markers and radius still work.':'plus OpenStreetMap streets. Only map coordinates are requested from the tile provider.'}`;}
function pin(h,origin=false){
 const state=h.state.toLowerCase(),marker=L.marker([h.lat,h.lng],{icon:L.divIcon({className:'',html:`<div class="hospital-pin ${origin?'origin':state}">${origin?'★':h.short[0]}</div>`,iconSize:[28,28],iconAnchor:[14,14]}),title:`${h.name} — ${h.state}`,keyboard:true});
 marker.addTo(markers).on('click',()=>select(h.id));marker.getElement().dataset.testid='map-pin-'+h.id;marker.getElement().setAttribute('aria-label',`${h.name}, ${h.state}. Show hospital details.`);return marker;
}
function updateMap(){
 markers.clearLayers();const rows=filtered(),origin=ready.find(h=>h.id===current);pin(origin,true);rows.forEach(h=>pin(h));
 if(radiusLayer)map.removeLayer(radiusLayer);radiusLayer=L.circle([origin.lat,origin.lng],{radius:radius*1000,color:'#315f9c',weight:1.5,dashArray:'6 5',fillOpacity:.025,interactive:false}).addTo(map);
 $('#map-count').textContent=`${rows.length} within ${radius} km`;
 $('#map-results').innerHTML=rows.length?rows.map(h=>`<button class="map-hospital-button ${selected===h.id?'selected':''}" data-select="${h.id}" data-testid="map-select-${h.id}"><strong>${esc(h.name)}</strong><small>${Math.round(distance(origin,h))} km · ${esc(h.resources.join(' · '))}</small>${tag(h.state,h.state==='Closed'?'critical':h.state==='Limited'?'warning':'')}</button>`).join(''):'<div class="empty-map">No hospitals match these filters. Widen the radius or change availability/resource.</div>';
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>select(b.dataset.select));
 if(selected&&(selected===current||rows.some(h=>h.id===selected)))showDetail(selected);else{selected=null;$('#hospital-map-detail').innerHTML='<h2>Select a hospital</h2><p class="muted">Click a marker or choose a hospital from the nearby list.</p>';}
}
function fitNearby(){const origin=hospitalById(current),bounds=L.latLngBounds([[origin.lat,origin.lng],...filtered().map(h=>[h.lat,h.lng])]);map.fitBounds(bounds.pad(.04),{maxZoom:11,padding:[25,25]});}
function select(id){selected=id;showDetail(id);document.querySelectorAll('[data-select]').forEach(b=>b.classList.toggle('selected',b.dataset.select===id));const h=hospitalById(id);map.panTo([h.lat,h.lng]);if(innerWidth<=1000)$('#hospital-map-detail').scrollIntoView({block:'nearest',behavior:'smooth'});}
function showDetail(id){
 const h=ready.find(h=>h.id===id),origin=hospitalById(current);
 $('#hospital-map-detail').innerHTML=`<div class="eyebrow">${h.id===current?'YOUR SAMPLE HOSPITAL':'SELECTED SAMPLE HOSPITAL'}</div><h2>${esc(h.name)}</h2>${tag(h.state,h.state==='Closed'?'critical':h.state==='Limited'?'warning':'')}<p class="map-coordinate">${esc(h.town)}<br>${h.lat.toFixed(4)}°, ${h.lng.toFixed(4)}° · ${Math.round(distance(origin,h))} km straight-line</p><h3>Sample resources</h3><div class="resource-chips">${h.resources.map(r=>tag(r)).join('')}</div><h3>Availability last updated</h3><p class="muted">${esc(updated(h))}</p><h3>Sample coordination contact</h3><p>${esc(h.contact)}</p><p class="notice ${h.state==='Closed'?'warning':''}">${h.state==='Closed'?'Closed in the demo. Do not treat this facility as an available destination.':h.state==='Limited'?'Limited sample capacity: direct confirmation is required before accepting a destination.':'Open sample status: the receiving team must confirm suitability and capacity.'}</p><a class="secondary" href="/?role=hospital&hospital=${h.id}">Open this hospital’s desk</a><h3 style="margin-top:22px">Crew briefing preview</h3><p class="crew-brief">${esc(h.name)} · ${esc(h.town)} · ${esc(h.state)} · ${esc(h.resources.join(', '))}. Availability: ${esc(updated(h))}. Fictional coordination example; confirm directly. No ambulance instruction has been sent.</p>`;
}
function renderLedger(){
 const rows=requests.filter(r=>deskRole==='ems'?r.hospitalId===current:isIncoming(r,current,states)||r.acceptedHospitalId===current).filter(r=>view==='active'?r.status!=='Completed':view==='incoming'?isIncoming(r,current,states)&&r.status==='Awaiting responses':r.status==='Completed').filter(r=>[r.id,r.resource,name(r.hospitalId),...recipientIds(r,states).map(name),...r.responses.map(x=>name(x.hospitalId)),name(r.acceptedHospitalId)].join(' ').toLowerCase().includes(search.toLowerCase()));
 $('#ledger-count').textContent=`${rows.length} ${modes[view].toLowerCase()} for ${name(current)}`;
 $('#ledger-body').innerHTML=rows.map(r=>`<tr data-testid="ledger-${r.id}"><td><strong>${esc(r.id)} · ${esc(r.resource)}</strong><br>${tag(r.status,r.status==='Completed'?'':'blue')}<br><small>${esc(new Date(r.createdAt).toLocaleString())}</small></td><td><strong>${esc(r.delivery?.requester?.name||hospitalById(r.hospitalId).short+' coordination')}</strong><br><small>${esc(hospitalById(r.hospitalId).town)}</small></td><td><div class="routing-label">${Array.isArray(r.delivery?.recipientIds)?'Saved recipients at send time':'Current matches — historical recipients not recorded'}</div><div class="ledger-links">${recipientIds(r,states).length?recipientIds(r,states).map(id=>`<a href="${route('nearby')}&selected=${id}&radius=${Math.max(100,r.radiusKm)}">${esc(name(id))}</a>`).join(''):'No matching recipients'}</div></td><td>${r.acceptedHospitalId?`<div>${esc(name(r.acceptedHospitalId))}<br><small>${r.delivery?.acceptedAt?'Accepted '+esc(new Date(r.delivery.acceptedAt).toLocaleString()):'Earlier recorded destination'}</small></div>`:'Awaiting hospital acceptance'}</td><td>${r.acceptedHospitalId?`<strong>${esc(name(r.acceptedHospitalId))}</strong><br><small>${esc(hospitalById(r.acceptedHospitalId).contact)}</small>`:'No destination accepted'}</td><td><a class="secondary" data-testid="ledger-detail-${r.id}" href="/?role=${deskRole}&hospital=${current}&request=${r.id}">Open details</a></td></tr>`).join('');
 $('#ledger-empty').innerHTML=rows.length?'':'<div class="empty">No matching requests in this view. Try a different hospital or search.</div>';
}
async function refresh(){const b=$('#refresh-overview');if(b)b.disabled=true;try{await load();}catch(e){$('#overview-error').className='error';$('#overview-error').textContent=e.message;}finally{if(b)b.disabled=false;}}
async function load(){
 // Establish the browser's test-scope cookie before parallel reads.
 const data=await read('/api/requests'),r=await read('/api/readiness');requests=data.requests;ready=r.facilities;states=Object.fromEntries(ready.map(h=>[h.id,h.state]));if(map){map.remove();map=undefined;tiles=undefined;radiusLayer=undefined;markers=L.layerGroup();}layout();
}
load().catch(e=>{$('#overview').innerHTML=`<main class="overview-wrap"><h1>Hospital Connect</h1><p role="alert">${esc(e.message)}</p><button id="retry" class="primary">Retry</button><p><a href="/">Back to dashboard</a></p></main>`;$('#retry').onclick=()=>location.reload();});
